import React, { useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Pencil, Save, Loader2 } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { useLecturerClasses } from '@/hooks/useClasses';
import { useClassStudents } from '@/hooks/useAttendances';
import { useGrades, useBulkUpdateGrades } from '@/hooks/useGrades';
import { useGradeManager } from '@/features/shared/classSummary/hooks';
import {
  extractNumeric,
  extractString,
  calculateNumericGrade,
  calculateLetterGrade,
  getStudentKrsId,
  generateGradeKey,
} from '@/features/shared/classSummary/utils';
import { apiService } from '@/services/api';
import type { GradeRecord, BulkGradeItem } from '@/types';

const GradeInput: React.FC = () => {
  const { user, currentSemester } = useAuth();
  const [selectedClassId, setSelectedClassId] = useState<number | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [saveAllStatus, setSaveAllStatus] = useState<'idle' | 'saving' | 'done'>('idle');
  
  const employeeId = user?.employeeId;

  // Fetch lecturer's classes
  const { data: lecturerClasses = [], isLoading: loadingClasses } = useLecturerClasses(
    employeeId || undefined,
    { semester: currentSemester }
  );
  
  // Auto-select first class - use 'id' property (API returns 'id' not 'kelas_id')
  const classId = selectedClassId ?? (lecturerClasses.length > 0 && lecturerClasses[0]?.id ? lecturerClasses[0].id : null);

  // Fetch class data (for bobot weights)
  const { data: classData } = useQuery({
    queryKey: ['class', classId],
    queryFn: () => apiService.getClassById(classId!),
    enabled: !!classId,
  });

  // Fetch students for selected class
  const { data: students = [], isLoading: loadingStudents } = useClassStudents(classId ?? undefined);
  
  // Fetch grade records for selected class
  const { data: gradeRecords = [], isLoading: loadingGrades } = useGrades(
    classId ? { kelas_id: classId } : undefined
  );

  // Use the grade manager hook from classSummary
  const gradeManager = useGradeManager({
    classIdNum: classId ?? 0,
    classId: classId ? String(classId) : undefined,
    students,
    gradeRecords,
    classData,
  });

  // Bulk grade update mutation
  const { mutateAsync: bulkUpdateGrades } = useBulkUpdateGrades();

  const {
    editedGrades,
    savingGradeIds,
    completedGradeKeys,
    gradeWeights,
    gradeComponents,
    isSavingBobots,
    bobotError,
    isBobotCompleted,
    hasEditedBobots,
    findGradeForStudent,
    updateGradeField,
    saveGrade,
    handleBobotChange,
    saveBobots,
    cancelBobots,
    enableBobotEditing,
    setEditedGrades,
    setCompletedGradeKeys,
  } = gradeManager;

  // Enter/exit edit mode
  const enterEditMode = () => {
    gradeManager.enterEditMode();
    setIsEditing(true);
  };

  const exitEditMode = () => {
    gradeManager.exitEditMode();
    setIsEditing(false);
    setSaveAllStatus('idle');
  };

  // Save all grades
  const handleSaveAll = async () => {
    setSaveAllStatus('saving');
    try {
      // Save bobots first if changed
      if (hasEditedBobots) {
        const success = await saveBobots();
        if (!success) {
          setSaveAllStatus('idle');
          return;
        }
      }

      // Build bulk grade update items
      const gradesToSave: BulkGradeItem[] = [];
      
      for (const student of students) {
        const grade = findGradeForStudent(student) || ({ id: 0 } as GradeRecord);
        const studentKrsId = getStudentKrsId(student);
        const safeNim = student?.nim ?? '';
        const gradeKey = generateGradeKey(grade, studentKrsId, safeNim);

        if (editedGrades[gradeKey] && !completedGradeKeys.has(gradeKey)) {
          const edited = editedGrades[gradeKey];
          gradesToSave.push({
            krs_id: studentKrsId ?? 0,
            aktivitas_partisipatif: extractNumeric(edited.aktivitas_partisipatif) ?? undefined,
            tugas: extractNumeric(edited.tugas) ?? undefined,
            quiz: extractNumeric(edited.quiz) ?? undefined,
            uts: extractNumeric(edited.uts) ?? undefined,
            uas: extractNumeric(edited.uas) ?? undefined,
            hasil_proyek: extractNumeric(edited.hasil_proyek) ?? undefined,
            nilai_angka: extractNumeric(edited.nilai_angka) ?? undefined,
            nilai_huruf: (() => {
              const val = extractString(edited.nilai_huruf as string | null | undefined);
              return val || undefined;
            })(),
            nilai_indeks: extractNumeric(edited.nilai_indeks) ?? undefined,
          });
        }
      }

      // Use bulk update API if there are grades to save
      if (gradesToSave.length > 0 && classId) {
        await bulkUpdateGrades({ classId, grades: gradesToSave });
      }

      setSaveAllStatus('done');
      setTimeout(() => {
        exitEditMode();
      }, 1000);
    } catch {
      setSaveAllStatus('idle');
    }
  };

  // Selected class info
  const selectedClassInfo = useMemo(() => {
    if (!classId) return null;
    return lecturerClasses.find((c) => c.id === classId) ?? null;
  }, [classId, lecturerClasses]);

  // Total weight for display
  const totalWeight = useMemo(
    () =>
      gradeWeights.aktivitas_partisipatif +
      gradeWeights.hasil_proyek +
      gradeWeights.quiz +
      gradeWeights.tugas +
      gradeWeights.uts +
      gradeWeights.uas,
    [gradeWeights]
  );

  const isLoading = !employeeId || loadingClasses || loadingStudents || loadingGrades;
  
  // Grade component labels for table headers
  const gradeComponentLabels = [
    { key: 'aktivitas_partisipatif', label: 'Participation', bobotKey: 'bobot_partisipatif' },
    { key: 'hasil_proyek', label: 'Project', bobotKey: 'bobot_proyek' },
    { key: 'quiz', label: 'Quiz', bobotKey: 'bobot_kuis' },
    { key: 'tugas', label: 'Assignment', bobotKey: 'bobot_tugas' },
    { key: 'uts', label: 'Midterm', bobotKey: 'bobot_uts' },
    { key: 'uas', label: 'Final', bobotKey: 'bobot_uas' },
  ] as const;

  // Weight key mapping for display
  const weightKeyMap: Record<string, keyof typeof gradeWeights> = {
    aktivitas_partisipatif: 'aktivitas_partisipatif',
    hasil_proyek: 'hasil_proyek',
    quiz: 'quiz',
    tugas: 'tugas',
    uts: 'uts',
    uas: 'uas',
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-900">Grade Input</h1>
        <div className="flex items-center gap-3">
          {classId && !isLoading && (
            <>
              {!isEditing ? (
                <button
                  onClick={enterEditMode}
                  className="btn btn-primary inline-flex items-center"
                  disabled={students.length === 0}
                >
                  <Pencil className="h-4 w-4 mr-2" /> Edit Grades
                </button>
              ) : (
                <>
                  <button
                    onClick={handleSaveAll}
                    disabled={saveAllStatus === 'saving'}
                    className="btn btn-primary inline-flex items-center"
                  >
                    {saveAllStatus === 'saving' ? (
                      <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Saving...</>
                    ) : saveAllStatus === 'done' ? (
                      <><Save className="h-4 w-4 mr-2" /> Saved!</>
                    ) : (
                      <><Save className="h-4 w-4 mr-2" /> Save All</>
                    )}
                  </button>
                  <button onClick={exitEditMode} className="btn inline-flex items-center">
                    Cancel
                  </button>
                </>
              )}
            </>
          )}
        </div>
      </div>

      {/* Class selector */}
      <div className="card">
        <div className="flex items-center justify-between">
          <div>
            <div className="font-semibold text-gray-900">Class</div>
            <div className="text-sm text-gray-500">Select a class to input grades</div>
          </div>
          <select
            className="border rounded-lg px-3 py-2"
            value={classId ?? ''}
            onChange={(e) => {
              const val = Number(e.target.value);
              setSelectedClassId(val || null);
              if (isEditing) exitEditMode();
            }}
            disabled={loadingClasses}
          >
            {loadingClasses && <option key="__loading" value="">Loading...</option>}
            {!loadingClasses && lecturerClasses.length === 0 && <option key="__empty" value="">No classes found</option>}
            {lecturerClasses.map((c) => (
              <option key={c.id} value={c.id}>
                {c.nama_mk} ({c.nama_kelas})
              </option>
            ))}
          </select>
        </div>
        {selectedClassInfo && (
          <div className="mt-2 text-sm text-gray-500">
            Course Code: {selectedClassInfo.kode_mk} &middot; Semester: {selectedClassInfo.semester}
          </div>
        )}
      </div>

      {/* Loading state */}
      {isLoading && (
        <div className="card flex items-center justify-center py-12">
          <Loader2 className="h-6 w-6 animate-spin text-gray-400 mr-3" />
          <span className="text-gray-500">Loading grade data...</span>
        </div>
      )}

      {/* Grades table */}
      {!isLoading && classId && (
        <div className="card p-0">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-gray-900">Grades Overview</h3>
              {students.length > 0 && (
                <span className="text-sm text-gray-500">{students.length} students</span>
              )}
            </div>

            {students.length === 0 ? (
              <div className="text-center py-8 text-gray-500">No students enrolled in this class.</div>
            ) : (
              <div className="border border-gray-300 rounded-lg overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full border-collapse text-xs">
                    <thead>
                      <tr className="bg-gray-50">
                        <th className="border-r border-b border-gray-300 px-3 py-2 text-left font-semibold text-gray-700 w-28">
                          NIM
                        </th>
                        <th className="border-r border-b border-gray-300 px-3 py-2 text-left font-semibold text-gray-700 w-48">
                          Name
                        </th>
                        {gradeComponentLabels.map(({ label }) => (
                          <th key={label} className="border-r border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-700 w-24">
                            {label}
                          </th>
                        ))}
                        <th className="border-r border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-700 w-20">
                          <div className="flex flex-col items-center">
                            <span>Numeric</span>
                            <span className="text-xs font-normal text-gray-500">(Auto)</span>
                          </div>
                        </th>
                        <th className="border-r border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-700 w-20">
                          <div className="flex flex-col items-center">
                            <span>Letter</span>
                            <span className="text-xs font-normal text-gray-500">(Auto)</span>
                          </div>
                        </th>
                        <th className={`border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-700 w-20 ${isEditing ? 'border-r' : ''}`}>
                          <div className="flex flex-col items-center">
                            <span>Index</span>
                            <span className="text-xs font-normal text-gray-500">(Auto)</span>
                          </div>
                        </th>
                        {isEditing && (
                          <th className="border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-700 w-16">
                            Action
                          </th>
                        )}
                      </tr>
                    </thead>
                    <tbody>
                      {students.map((student) => {
                        const grade = findGradeForStudent(student) || ({
                          id: 0,
                          krs_id: null,
                          aktivitas_partisipatif: null,
                          hasil_proyek: null,
                          quiz: null,
                          tugas: null,
                          uts: null,
                          uas: null,
                          nilai_angka: null,
                          nilai_huruf: null,
                          nilai_indeks: null,
                        } as GradeRecord);

                        const studentKrsId = getStudentKrsId(student);
                        const gradeKey = generateGradeKey(grade, studentKrsId, student.nim ?? '');
                        const isCompleted = completedGradeKeys.has(gradeKey);
                        const isRowEditing = isEditing && !isCompleted;
                        const isSaving = grade.id ? savingGradeIds.has(grade.id) : false;
                        const edited = editedGrades[gradeKey] || grade;

                        // Helper to get display value (handles SqlNull types)
                        const getValue = (key: keyof GradeRecord): string | number | '' => {
                          const val = edited[key];
                          if (val === null || val === undefined) return '';
                          if (typeof val === 'object' && 'Float64' in val) return val.Valid ? val.Float64 : '';
                          if (typeof val === 'object' && 'String' in val) return val.Valid ? val.String : '';
                          if (typeof val === 'object' && 'Int32' in val) return val.Valid ? val.Int32 : '';
                          if (typeof val === 'number' || typeof val === 'string') return val;
                          return '';
                        };

                        // Auto-calculated values
                        const nilaiAngkaValue = getValue('nilai_angka');
                        const displayNumeric = nilaiAngkaValue !== '' ? nilaiAngkaValue : (isEditing && edited ? calculateNumericGrade(edited, gradeComponents) : null);
                        const normalizedNumeric = typeof displayNumeric === 'string' ? Number(displayNumeric) : displayNumeric;
                        const { huruf: calcHuruf, indeks: calcIndeks } = normalizedNumeric !== null && normalizedNumeric !== undefined ? calculateLetterGrade(normalizedNumeric) : { huruf: '', indeks: 0 };
                        const nilaiHurufValue = getValue('nilai_huruf');
                        const displayHuruf = nilaiHurufValue !== '' ? nilaiHurufValue : calcHuruf;
                        const nilaiIndeksValue = getValue('nilai_indeks');
                        const displayIndeks = nilaiIndeksValue !== '' ? nilaiIndeksValue : calcIndeks;

                        return (
                          <tr key={student.nim} className="hover:bg-gray-50">
                            <td className="border-r border-b border-gray-300 px-3 py-2 font-medium text-gray-900 w-28">
                              {student.nim}
                            </td>
                            <td className="border-r border-b border-gray-300 px-3 py-2 text-gray-900 w-48">
                              {student.nama}
                            </td>
                            {gradeComponentLabels.map(({ key }) => (
                              <td key={key} className="border-r border-b border-gray-300 px-3 py-2 text-center w-24">
                                {isRowEditing ? (
                                  <input
                                    type="number"
                                    step="0.1"
                                    value={getValue(key as keyof GradeRecord)}
                                    onChange={(e) =>
                                      updateGradeField(
                                        gradeKey,
                                        key as keyof GradeRecord,
                                        e.target.value ? parseFloat(e.target.value) : null
                                      )
                                    }
                                    className="input-field text-xs w-full [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                                  />
                                ) : (
                                  <span className="text-gray-600">
                                    {(() => {
                                      const v = getValue(key as keyof GradeRecord);
                                      return v !== '' ? v : '-';
                                    })()}
                                  </span>
                                )}
                              </td>
                            ))}
                            {/* Numeric (Auto) */}
                            <td className="border-r border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-900 w-20">
                              <div className={`px-2 py-1 rounded ${isRowEditing ? 'bg-blue-50 text-blue-900' : ''}`}>
                                <span>{displayNumeric !== null && displayNumeric !== '' ? displayNumeric : '-'}</span>
                                {isRowEditing && displayNumeric !== null && displayNumeric !== '' && (
                                  <span className="text-xs text-blue-600 ml-1">✓</span>
                                )}
                              </div>
                            </td>
                            {/* Letter (Auto) */}
                            <td className="border-r border-b border-gray-300 px-3 py-2 text-center font-bold text-blue-600 w-20">
                              <div className={`px-2 py-1 rounded ${isRowEditing ? 'bg-blue-50' : ''}`}>
                                <span>{displayHuruf || '-'}</span>
                                {isRowEditing && displayHuruf && (
                                  <span className="text-xs ml-1">✓</span>
                                )}
                              </div>
                            </td>
                            {/* Index (Auto) */}
                            <td className={`border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-900 w-20 ${isEditing ? 'border-r' : ''}`}>
                              <div className={`px-2 py-1 rounded ${isRowEditing ? 'bg-blue-50 text-blue-900' : ''}`}>
                                <span>{displayIndeks || '-'}</span>
                                {isRowEditing && displayIndeks && (
                                  <span className="text-xs text-blue-600 ml-1">✓</span>
                                )}
                              </div>
                            </td>
                            {/* Action Column */}
                            {isEditing && (
                              <td className="border-b border-gray-300 px-3 py-2 text-center">
                                {isCompleted ? (
                                  <button
                                    onClick={() => {
                                      setCompletedGradeKeys((prev) => {
                                        const next = new Set(prev);
                                        next.delete(gradeKey);
                                        return next;
                                      });
                                      const currentGrade = findGradeForStudent(student);
                                      if (currentGrade) {
                                        setEditedGrades((prev) => ({
                                          ...prev,
                                          [gradeKey]: currentGrade,
                                        }));
                                      }
                                    }}
                                    className="px-2 py-1 text-xs rounded bg-blue-600 text-white hover:bg-blue-700"
                                  >
                                    Edit
                                  </button>
                                ) : (
                                  <div className="flex gap-2 justify-center">
                                    <button
                                      onClick={() => saveGrade(gradeKey, grade, student)}
                                      disabled={isSaving}
                                      className="px-2 py-1 text-xs rounded bg-green-600 text-white hover:bg-green-700 disabled:opacity-50"
                                    >
                                      {isSaving ? '...' : 'Save'}
                                    </button>
                                    <button
                                      onClick={() => {
                                        const originalGrade = findGradeForStudent(student);
                                        if (originalGrade) {
                                          setEditedGrades((prev) => ({
                                            ...prev,
                                            [gradeKey]: originalGrade,
                                          }));
                                        } else {
                                          setEditedGrades((prev) => {
                                            const next = { ...prev };
                                            delete next[gradeKey];
                                            return next;
                                          });
                                        }
                                        setCompletedGradeKeys((prev) => new Set([...prev, gradeKey]));
                                      }}
                                      disabled={isSaving}
                                      className="px-2 py-1 text-xs rounded bg-gray-200 text-gray-700 hover:bg-gray-300 disabled:opacity-50"
                                    >
                                      Cancel
                                    </button>
                                  </div>
                                )}
                              </td>
                            )}
                          </tr>
                        );
                      })}
                      {/* Grade Weights Row */}
                      <tr className="bg-blue-50 font-bold">
                        <td colSpan={2} className="border-r border-b border-gray-300 px-3 py-2 text-gray-900">
                          Component Weights
                          {isEditing && (
                            <div className="text-xs font-normal text-gray-500 mt-1">
                              (Total must be 100%)
                            </div>
                          )}
                        </td>
                        {gradeComponentLabels.map(({ key, bobotKey }) => (
                          <td key={key} className="border-r border-b border-gray-300 px-3 py-2 text-center text-blue-600 w-24">
                            {isEditing ? (
                              <input
                                type="text"
                                value={gradeWeights[weightKeyMap[key]]}
                                onChange={(e) => handleBobotChange(bobotKey, e.target.value)}
                                className="w-full px-2 py-1 text-center border border-blue-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                              />
                            ) : (
                              `${gradeWeights[weightKeyMap[key]]}%`
                            )}
                          </td>
                        ))}
                        <td colSpan={3} className="border-r border-b border-gray-300 px-3 py-2 text-center font-semibold text-gray-900">
                          <div className={totalWeight === 100 ? 'text-green-600' : 'text-red-600'}>
                            Total: {totalWeight.toFixed(1)}%
                          </div>
                          {bobotError && (
                            <div className="text-xs text-red-600 mt-1">{bobotError}</div>
                          )}
                        </td>
                        {isEditing && (
                          <td className="border-b border-gray-300 px-3 py-2 text-center">
                            {isBobotCompleted ? (
                              <button
                                onClick={enableBobotEditing}
                                className="px-2 py-1 text-xs rounded bg-blue-600 text-white hover:bg-blue-700"
                              >
                                Edit
                              </button>
                            ) : (
                              <div className="flex gap-2 justify-center">
                                <button
                                  onClick={() => saveBobots()}
                                  disabled={isSavingBobots}
                                  className="px-2 py-1 text-xs rounded bg-green-600 text-white hover:bg-green-700 disabled:opacity-50"
                                >
                                  {isSavingBobots ? '...' : 'Save'}
                                </button>
                                <button
                                  onClick={cancelBobots}
                                  disabled={isSavingBobots}
                                  className="px-2 py-1 text-xs rounded bg-gray-200 text-gray-700 hover:bg-gray-300 disabled:opacity-50"
                                >
                                  Cancel
                                </button>
                              </div>
                            )}
                          </td>
                        )}
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Empty state when no class selected */}
      {!isLoading && !classId && employeeId && (
        <div className="card flex items-center justify-center py-12">
          <span className="text-gray-500">No classes available for grade input.</span>
        </div>
      )}
    </div>
  );
};

export default GradeInput;
